[class*="ApplicationMenuPageHeader-"]::after {
    background-color: transparent !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    border-bottom: none !important;
    box-shadow: none !important;
}

/* ================= 5. 主输入框 (Composer) 雾化透明毛玻璃微光胶囊 ================= */
:is(.composer-surface-chrome, [class*="_ComposerLayoutRoot_"], [class*="ComposerLayoutRoot-"], [data-composer-surface-variant][data-composer-radius-variant]) {
    background-color: rgba(14, 22, 19, 0.24) !important;
    background: rgba(14, 22, 19, 0.24) !important;
    backdrop-filter: blur(12px) saturate(125%) brightness(108%) !important;
    -webkit-backdrop-filter: blur(12px) saturate(125%) brightness(108%) !important;
    border: 1px solid rgba(255, 255, 255, 0.16) !important;
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.22), inset 0 1px 0 0 rgba(255, 255, 255, 0.16) !important;
    border-radius: 16px !important;
    transform: translateZ(0) !important;
    transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease !important;
}

/* 输入框聚焦时提升微光边缘与通透饱和度 */
:is(.composer-surface-chrome, [class*="_ComposerLayoutRoot_"], [class*="ComposerLayoutRoot-"], [data-composer-surface-variant][data-composer-radius-variant]):focus-within {
    background-color: rgba(18, 28, 24, 0.32) !important;
    background: rgba(18, 28, 24, 0.32) !important;
    border-color: rgba(255, 255, 255, 0.28) !important;
    box-shadow: 0 8px 36px 0 rgba(0, 0, 0, 0.30), 0 0 0 1px rgba(255, 255, 255, 0.18) !important;
}

/* 输入框内部主体容器与尾部思考强度条透明化 (消除主页 Home 实体黑底及图像页 trailing surface 灰黑块) */
:is([class*="_ComposerLayoutBody_"], [class*="ComposerLayoutBody-"], [data-composer-body]) {
    background-color: transparent !important;
    background: transparent !important;
    box-shadow: none !important;
}

[class*="bg-(--composer-layout-surface-background)"]:not([data-composer-surface-variant]) {
    background-color: rgba(255, 255, 255, 0.08) !important;
    border: 1px solid rgba(255, 255, 255, 0.14) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
}

[class*="composerContext-"],
[class*="ComposerLayoutReplyContext-"] {
    background: rgba(255, 255, 255, 0.06) !important;
    background-color: rgba(255, 255, 255, 0.06) !important;
}

/* 输入框底部工具栏与操作按钮条保持透明 */
:is(.composer-surface-chrome [class*="_footer_"], [class*="_ComposerLayoutRoot_"] [class*="_ComposerLayoutFooter_"], [class*="ComposerLayoutRoot-"] [class*="ComposerLayoutFooter-"]) {
    background-color: transparent !important;
    background: transparent !important;
    border-top: 1px solid rgba(255, 255, 255, 0.06) !important;
}

/* 输入框 '+' 展开顶部浮层菜单 (ComposerTopMenuPanel / expanded-top-tray) 磨砂玻璃化并防穿透重叠 */
[class*="ComposerTopMenuPanel-"][data-composer-expanded-top-tray],
[data-composer-expanded-top-tray] {
    background: rgba(18, 24, 30, 0.80) !important;
    background-color: rgba(18, 24, 30, 0.80) !important;
    backdrop-filter: blur(24px) saturate(160%) !important;
    -webkit-backdrop-filter: blur(24px) saturate(160%) !important;
    border: 1px solid rgba(255, 255, 255, 0.16) !important;
    border-radius: 16px !important;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.40) !important;
    position: relative !important;
    z-index: 35 !important;
}

/* 【核心修复】消除输入框底部宿主容器、渐变遮罩及 ::before / ::after 伪元素实黑边缘 (根除新版 footer-A8ZvKV 黑条黑角) */
[data-thread-scroll-footer],
[data-thread-footer-background],
[data-thread-footer-background] > div,
[data-thread-footer-background] [class*="surface-"],
[data-thread-footer-background] [class*="fade-"],
[class*="EnterpriseFooterBackground-"],
[class*="thread-scroll-layout"] [class*="footer-"],
[class*="thread-scroll-layout"] [class*="footer-"]::before,
[class*="thread-scroll-layout"] [class*="footer-"]::after,
div[class*="footer-"][class*="shiftWithTranscript-"],
div[class*="footer-"][class*="shiftWithTranscript-"]::before,
div[class*="footer-"][class*="shiftWithTranscript-"]::after,
div[class*="footer-"]:has([data-thread-composer-backdrop]),
div[class*="footer-"]:has([data-thread-composer-backdrop])::before,
div[class*="footer-"]:has([data-thread-composer-backdrop])::after,
div[class*="pointer-events-none"][class*="inset-x-0"]:is([class*="bg-surface"], [class*="-top-8"], [class*="bottom-0"], [class*="footer-"]),
div[class*="pointer-events-none"][class*="inset-x-0"]::before,
