[class*="thread-scroll-layout"] div:has(> [data-codex-composer-root]),
[class*="thread-scroll-layout"] div[class*="pointer-events-none"][class*="bottom-0"],
[class*="thread-scroll-layout"] div[class*="pointer-events-none"][class*="bottom-0"]::before,
[class*="thread-scroll-layout"] div[class*="pointer-events-none"][class*="bottom-0"]::after,
div:is([class*="bg-gradient-to-t"], [class*="bg-linear-to-t"], [class*="bg-linear-to-b"], [class*="from-surface"], [class*="via-surface"], [class*="to-surface"]):not(button, [class*="preview"], :has(webview), :has(iframe)),
div[class*="from-surface-secondary"]:not(button, [class*="preview"]),
div[class*="before:from-surface"]::before,
div[class*="after:from-surface"]::after,
